INSERT INTO `tutors` (`id`, `user_id`, `bio`, `experience_years`, `created_at`, `updated_at`) VALUES
(1, 61, 'Esse ut iste et qui autem maiores hic. Facilis voluptatem mollitia dignissimos ex est eum qui. Quia impedit qui magni exercitationem totam.', 11, '2025-10-27 16:10:24', '2025-10-27 16:10:24'),
(2, 80, 'Et modi tempore sed amet odit excepturi a. Cumque iste nemo sunt maiores porro et animi.', 6, '2025-10-27 16:10:24', '2025-10-27 16:10:24'),
(3, 45, 'Expedita sequi aut iste minima eligendi rerum nemo. Nihil ducimus atque eius facilis quos.', 8, '2025-10-27 16:10:24', '2025-10-27 16:10:24'),
(4, 31, 'Aut illum dolorum exercitationem nihil et molestiae qui. Accusamus animi pariatur vel reprehenderit iusto ut. Numquam sapiente est corrupti et.', 1, '2025-10-27 16:10:24', '2025-10-27 16:10:24'),
(5, 56, 'Dolorem est explicabo modi veniam sit aut voluptas. Non sint accusamus facilis tenetur.', 14, '2025-10-27 16:10:24', '2025-10-27 16:10:24'),
(6, 72, 'Velit natus necessitatibus sunt et qui cupiditate voluptatum laborum. Id culpa nulla rerum deserunt aut. Dolore est alias commodi minus.', 7, '2025-10-27 16:10:24', '2025-10-27 16:10:24'),
(7, 58, 'Est et unde saepe qui odit repellat rerum. Hic harum doloribus est et. Omnis et consectetur voluptatum aut.', 10, '2025-10-27 16:10:24', '2025-10-27 16:10:24'),
(8, 15, 'Voluptatem expedita est est atque exercitationem. Ut eos culpa voluptates sed cumque quam. Quibusdam magnam reiciendis est quo aut atque optio nesciunt.', 7, '2025-10-27 16:10:24', '2025-10-27 16:10:24'),
(9, 71, 'Consequatur iusto sit nam quia tempora cumque beatae. Voluptas reiciendis consequuntur ea aut. Dolor enim necessitatibus eos.', 15, '2025-10-27 16:10:24', '2025-10-27 16:10:24'),
(10, 96, 'Et quas et reprehenderit quos error adipisci. Sed placeat ratione iusto nihil. Unde omnis facilis fugiat qui deserunt enim.', 14, '2025-10-27 16:10:24', '2025-10-27 16:10:24'),
(11, 41, 'Voluptas architecto quidem ipsa tenetur tempora. Minus non sequi quia sunt qui.', 4, '2025-10-27 16:10:24', '2025-10-27 16:10:24'),
(12, 6, 'Iure dolor nam sed fugit. Exercitationem dicta ab expedita et inventore neque ea. Aperiam excepturi ut odit voluptatem quas consequatur.', 13, '2025-10-27 16:10:24', '2025-10-27 16:10:24'),
(13, 77, 'Facilis dolorem voluptate vel sapiente qui. Atque numquam accusantium illum voluptatem.', 10, '2025-10-27 16:10:24', '2025-10-27 16:10:24'),
(14, 86, 'Dolores aut facilis temporibus et impedit. Molestiae fugiat laudantium ipsum numquam magnam ratione tempora excepturi.', 10, '2025-10-27 16:10:24', '2025-10-27 16:10:24'),
(15, 21, 'Impedit quasi assumenda et ut sunt sit repellendus. Dolore soluta eligendi officiis est omnis dolores nesciunt quis.', 4, '2025-10-27 16:10:24', '2025-10-27 16:10:24'),
(16, 68, 'Rerum eius voluptatibus omnis a alias ullam debitis. Suscipit tempora tenetur consectetur. At occaecati eum culpa voluptatem sed veritatis.', 6, '2025-10-27 16:10:24', '2025-10-27 16:10:24'),
(17, 82, 'Laboriosam illo quae qui molestiae. Et ipsum nobis minima quo est nam ab placeat. Nihil qui quae similique.', 5, '2025-10-27 16:10:24', '2025-10-27 16:10:24'),
(18, 46, 'Consequatur omnis quo illo at et alias. Modi voluptatum in excepturi et dolorem adipisci. Laudantium aut voluptatem voluptas recusandae et quis.', 7, '2025-10-27 16:10:24', '2025-10-27 16:10:24'),
(19, 73, 'Nam qui eligendi impedit nemo libero repellat. Ab quia enim vel ut dolorum.', 13, '2025-10-27 16:10:24', '2025-10-27 16:10:24'),
(20, 8, 'Nisi suscipit dolorum et consequatur odio culpa. Et sed fugiat facere autem ut voluptatem non.', 10, '2025-10-27 16:10:24', '2025-10-27 16:10:24'),
(21, 9, 'Laborum quisquam et perferendis sapiente ex laudantium maiores. Accusantium odio repellendus explicabo.', 4, '2025-10-27 16:10:24', '2025-10-27 16:10:24'),
(22, 94, 'Mollitia quia cupiditate non qui sunt necessitatibus. Eius numquam atque quia culpa similique asperiores qui.', 8, '2025-10-27 16:10:24', '2025-10-27 16:10:24'),
(23, 74, 'Totam voluptas praesentium consequatur ut enim nesciunt saepe. Nulla eius distinctio impedit et fugiat quia. Dolorum ut ducimus et deserunt sed ab similique.', 6, '2025-10-27 16:10:24', '2025-10-27 16:10:24'),
(24, 76, 'Autem fugit perspiciatis voluptatem odio. Sed ab facere ipsum ducimus deserunt quia.', 15, '2025-10-27 16:10:24', '2025-10-27 16:10:24'),
(25, 40, 'Nisi velit fuga nulla atque et labore recusandae. Iure nemo velit corporis quia.', 5, '2025-10-27 16:10:24', '2025-10-27 16:10:24');
